__NUXT_JSONP__("/rumbo-democratico/columnas/las_osc_pilares_de_la_gobernanza_democratica", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"las_osc_pilares_de_la_gobernanza_democratica",title:"Las OSC, pilares de la gobernanza democrática",date:"2026-04-17T21:44:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fde706240-f2e0-4b30-ae2f-a0104389da4d\u002F-\u002Fcrop\u002F921x493\u002F17,39\u002F-\u002Fpreview\u002F",autor:"Dalia Toledo",medio:"Animal Político",link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Fosc-gobernanza-democratica-colaboracion-gobierno\u002F",category:"rumbo-democratico",extracto:"Durante décadas, las OSC han contribuido de manera sustantiva a la vida pública: generan evidencia sobre los problemas y sus causas, diseñan e implementan soluciones innovadoras, acompañan a poblaciones vulnerables y trabajan en territorios donde la presencia del Estado es limitada o inexistente.",toc:[],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Aunque la "},{type:b,tag:c,props:{},children:[{type:a,value:f}]},{type:a,value:" no es un concepto nuevo, hoy más que nunca resulta necesario subrayar su importancia. Se trata de un enfoque de "},{type:b,tag:c,props:{},children:[{type:a,value:"gestión pública"}]},{type:a,value:" en el que la solución de los problemas comunes no recae exclusivamente en el Estado, sino que se construye en colaboración con actores sociales. Este modelo parte de una premisa fundamental: el "},{type:b,tag:c,props:{},children:[{type:a,value:h}]},{type:a,value:" por sí solo es insuficiente para responder a la complejidad de los desafíos actuales."}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"Frente a "},{type:b,tag:c,props:{},children:[{type:a,value:"problemas públicos"}]},{type:a,value:" cada vez más difíciles de atender y a "},{type:b,tag:c,props:{},children:[{type:a,value:"restricciones presupuestarias"}]},{type:a,value:" crecientes, la articulación de capacidades —no solo materiales, sino también técnicas, territoriales, de comunicación y otras— se vuelve indispensable. En este contexto, las "},{type:b,tag:c,props:{},children:[{type:a,value:g}]},{type:a,value:" no deben verse como actores complementarios, sino como pilares de la "},{type:b,tag:c,props:{},children:[{type:a,value:f}]},{type:a,value:i}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"Durante décadas, las "},{type:b,tag:c,props:{},children:[{type:a,value:g}]},{type:a,value:" han contribuido de manera sustantiva a la vida pública: generan evidencia sobre los problemas y sus causas, diseñan e implementan "},{type:b,tag:c,props:{},children:[{type:a,value:j}]},{type:a,value:" y soluciones innovadoras, acompañan a "},{type:b,tag:c,props:{},children:[{type:a,value:"poblaciones vulnerables"}]},{type:a,value:"y trabajan en territorios donde la presencia del Estado es limitada o inexistente. Por ello, su contribución al "},{type:b,tag:c,props:{},children:[{type:a,value:"bienestar social"}]},{type:a,value:" es innegable."}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"Sin embargo, actualmente enfrentan "},{type:b,tag:c,props:{},children:[{type:a,value:"barreras estructurales"}]},{type:a,value:" que restringen su acción: desde un financiamiento cada vez más limitado —que intensifica la competencia entre organizaciones y reduce los incentivos a la colaboración— hasta la disminución de espacios de "},{type:b,tag:c,props:{},children:[{type:a,value:"interlocución con el gobierno"}]},{type:a,value:", lo cual también afecta sus capacidades de incidencia. Aun cuando todos estos problemas son relevantes, es fundamental destacar la importancia de tender puentes entre las "},{type:b,tag:c,props:{},children:[{type:a,value:g}]},{type:a,value:" y el "},{type:b,tag:c,props:{},children:[{type:a,value:h}]},{type:a,value:i}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"Si bien los "},{type:b,tag:c,props:{},children:[{type:a,value:"espacios de participación ciudadana"}]},{type:a,value:" se han reducido en los últimos años, esta tendencia ha comenzado a revertirse en algunos gobiernos e instituciones con voluntad de construir agendas conjuntas. A pesar de este avance, persiste una profunda "},{type:b,tag:c,props:{},children:[{type:a,value:"desconfianza institucional"}]},{type:a,value:" entre los actores sociales que dificulta la articulación de esfuerzos y ralentiza los procesos de colaboración."}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"No obstante, los beneficios de diseñar e implementar "},{type:b,tag:c,props:{},children:[{type:a,value:"soluciones conjuntas"}]},{type:a,value:" son mayores, por lo que vale la pena comenzar a reconstruir y fortalecer puentes con aquellos actores que tienen la voluntad para hacerlo."}]},{type:a,value:e},{type:b,tag:d,props:{},children:[{type:a,value:"La evidencia muestra que un modelo de gestión como el que propone la "},{type:b,tag:c,props:{},children:[{type:a,value:f}]},{type:a,value:" fortalece la "},{type:b,tag:c,props:{},children:[{type:a,value:"confianza en las instituciones"}]},{type:a,value:", mejora la calidad de las "},{type:b,tag:c,props:{},children:[{type:a,value:j}]},{type:a,value:", fomenta la "},{type:b,tag:c,props:{},children:[{type:a,value:"inclusión"}]},{type:a,value:" y amplía la "},{type:b,tag:c,props:{},children:[{type:a,value:"participación ciudadana"}]},{type:a,value:". En este sentido, avanzar en esquemas de colaboración efectiva —aunque sea a través de logros graduales y espacios acotados de cocreación— no solo es deseable, sino necesario en el contexto actual."}]}]},dir:"\u002Fcolumnas",path:"\u002Fcolumnas\u002Flas_osc_pilares_de_la_gobernanza_democratica",extension:".md",createdAt:k,updatedAt:k},columnas:[]}],fetch:{},mutations:[]}}("text","element","strong","p","\n","gobernanza democrática","OSC","gobierno",".","políticas públicas","2026-07-19T00:56:17.191Z")));